import { flushSync } from 'react-dom';
import { Field as BaseField } from '@base-ui/react/field';
import { NumberInput, type NumberInputProps } from '../number-input/NumberInput';
import { Slider as BaseSlider } from '@base-ui/react/slider';
import {
  useState,
  Fragment,
  Children,
  cloneElement,
  isValidElement,
  type ComponentProps,
  type ReactNode,
  type Ref,
} from 'react';
import { cn } from '../../utils/cn';
import { sliderVariants, sliderInputVariants, sliderMarkVariants, type SliderVariantProps } from './slider.variants';

import { markKeyDown } from './slider-marks-keyboard';
import { normalizeMarks, SliderMarkLabels, type SliderMark } from './SliderMarks';

export interface SliderProps extends Omit<BaseSlider.Root.Props, 'className' | 'children'>, SliderVariantProps {
  /** Decorative ticks and optional string labels within min and max. */
  marks?: SliderMark[];
  /** Restrict thumb keyboard navigation to marks. Pointer dragging still uses step. */
  restrictToMarks?: boolean;
  /** Pair each thumb with an editable NumberInput; the slider remains the form control. */
  withInput?: boolean;
  /** Paired input presentation. Size defaults to the slider size. */
  inputProps?: Pick<NumberInputProps, 'unit' | 'hideSteppers' | 'size'>;
  className?: string;
  ref?: Ref<HTMLDivElement>;
  /** Visible label; labels every thumb. Without it, pass `aria-label` (single) or `thumbLabels`. */
  label?: ReactNode;
  /** Marks every thumb invalid; pair with a FieldError or description. */
  invalid?: boolean;
  /** Accessible name of a single thumb when there is no visible label. */
  'aria-label'?: string;
  /** Per-thumb accessible names for range sliders, e.g. `['Minimum', 'Maximum']`. */
  thumbLabels?: string[];
  /** Show the formatted value next to the label. */
  showValue?: boolean;
  /** Custom value text; receives formatted strings and raw numbers. */
  formatValue?: (formatted: readonly string[], values: readonly number[]) => ReactNode;
}

// Base UI exposes the native range input through Thumb's public render children.
// Preserve its validation props unless the caller explicitly supplies an invalid state.
function invalidThumbChildren(
  children: ReactNode,
  ariaInvalid: ComponentProps<'input'>['aria-invalid'],
  decorate?: (props: ComponentProps<'input'>) => ComponentProps<'input'>,
): ReactNode {
  return Children.map(children, (child) => {
    if (!isValidElement<ComponentProps<'input'>>(child)) return child;
    if (child.type === 'input')
      return cloneElement(child, {
        ...decorate?.(child.props),
        'aria-invalid': ariaInvalid ?? child.props['aria-invalid'],
      });
    if (child.type === Fragment)
      return cloneElement(child, {}, invalidThumbChildren(child.props.children, ariaInvalid, decorate));
    return child;
  });
}

function thumbCount(value: SliderProps['value'], defaultValue: SliderProps['defaultValue']) {
  const v = value ?? defaultValue;
  return Array.isArray(v) ? v.length : 1;
}

// Construct the documented Slider callback details without importing Base UI internals.
function inputChangeDetails(event: Event, activeThumbIndex: number): BaseSlider.Root.ChangeEventDetails {
  let canceled = false;
  let propagationAllowed = false;
  return {
    event,
    activeThumbIndex,
    reason: 'input-change',
    trigger: undefined,
    cancel() {
      canceled = true;
    },
    allowPropagation() {
      propagationAllowed = true;
    },
    get isCanceled() {
      return canceled;
    },
    get isPropagationAllowed() {
      return propagationAllowed;
    },
  };
}

function snapInput(value: number, min: number, max: number, step: number) {
  const precision = (number: number) => {
    const [fraction = '', exponent = '0'] = number.toString().split('e');
    return Math.max(0, (fraction.split('.')[1]?.length ?? 0) - Number(exponent));
  };
  const decimals = Math.max(precision(step), precision(min));
  const snapped = Number((min + Math.round((value - min) / step) * step).toFixed(Math.min(100, decimals)));
  return Math.min(max, Math.max(min, snapped));
}

/**
 * Pick a number (or a range) on a track. Pass an array to `value` / `defaultValue` for a
 * range: one thumb per entry. Arrow keys step, Page Up/Down take `largeStep`, Home/End jump.
 */
export function Slider({
  size,
  marks,
  restrictToMarks = false,
  withInput = false,
  inputProps,
  invalid,
  'aria-invalid': ariaInvalidProp,
  label,
  'aria-label': ariaLabel,
  thumbLabels,
  showValue = false,
  formatValue = (formatted) => formatted.join(' – '),
  className,
  value,
  defaultValue,
  ...props
}: SliderProps) {
  const [internalState, setInternalState] = useState({
    value: value ?? defaultValue ?? props.min ?? 0,
    keyboard: false,
  });
  const rawValue = value ?? internalState.value;
  const currentValue = typeof rawValue === 'number' ? rawValue : [...rawValue].sort((a, b) => a - b);
  const v = sliderVariants({ size });
  const count = thumbCount(value, defaultValue);
  const ariaInvalid = ariaInvalidProp ?? (invalid || undefined);
  const normalizedMarks = normalizeMarks(marks, props.min ?? 0, props.max ?? 100);
  const hasLabels = normalizedMarks.some((mark) => mark.label !== undefined);
  const markStyles = sliderMarkVariants();
  const values = typeof currentValue === 'number' ? [currentValue] : currentValue;
  const change: NonNullable<SliderProps['onValueChange']> = (next, details) => {
    props.onValueChange?.(next, details);
    if (!details.isCanceled && value === undefined) setInternalState((state) => ({ ...state, value: next }));
  };
  const control = (
    <BaseSlider.Control className={cn(v.control(), hasLabels && 'mb-6')}>
      <BaseSlider.Track className={v.track()}>
        <BaseSlider.Indicator className={v.indicator()} />
        {normalizedMarks.map((mark) => (
          <span
            key={mark.value}
            data-slider-mark=""
            aria-hidden="true"
            className={markStyles.mark({
              active:
                mark.value >= (values.length > 1 ? (values[0] ?? 0) : (props.min ?? 0)) &&
                mark.value <= (values[values.length - 1] ?? 0),
            })}
            style={{
              insetInlineStart: `${((mark.value - (props.min ?? 0)) / ((props.max ?? 100) - (props.min ?? 0))) * 100}%`,
            }}
          />
        ))}
        {hasLabels && (
          <SliderMarkLabels marks={normalizedMarks} values={values} min={props.min ?? 0} max={props.max ?? 100} />
        )}
        {Array.from({ length: count }, (_, i) => (
          <BaseSlider.Thumb
            key={i}
            index={i}
            aria-label={thumbLabels?.[i] ?? (count === 1 ? ariaLabel : undefined)}
            className={v.thumb()}
            getAriaValueText={
              normalizedMarks.length
                ? (formatted, number) => {
                    const label = normalizedMarks.find((mark) => mark.value === number)?.label;
                    return label === undefined ? formatted : `${label}, ${formatted}`;
                  }
                : undefined
            }
            render={(thumbProps) => (
              <div {...thumbProps}>
                {invalidThumbChildren(
                  thumbProps.children,
                  ariaInvalid,
                  restrictToMarks && normalizedMarks.length > 0
                    ? (input) => ({
                        step: 'any',
                        onKeyDown: (event) => {
                          if (
                            !markKeyDown(
                              event,
                              input.onChange,
                              values,
                              i,
                              normalizedMarks.map((mark) => mark.value),
                              props.minStepsBetweenValues ?? 0,
                              (dispatch) => {
                                if (values.length < 2 || !props.minStepsBetweenValues) return dispatch();
                                // Mark spacing was checked above. Disable only Base UI's numeric
                                // gap for this synchronous keyboard dispatch; pointer handling
                                // retains the caller's gap and step, and creates its own details.
                                flushSync(() => setInternalState((state) => ({ ...state, keyboard: true })));
                                try {
                                  dispatch();
                                } finally {
                                  flushSync(() => setInternalState((state) => ({ ...state, keyboard: false })));
                                }
                              },
                            )
                          )
                            input.onKeyDown?.(event);
                        },
                      })
                    : undefined,
                )}
              </div>
            )}
          />
        ))}
      </BaseSlider.Track>
    </BaseSlider.Control>
  );
  if (withInput) {
    const inputStyles = sliderInputVariants();
    const values = typeof currentValue === 'number' ? [currentValue] : currentValue;
    const updateInput = (next: number | null, index: number, event: Event, commit = false) => {
      const number = values[index];
      if (next === null || number === undefined) return;
      const gap = (props.minStepsBetweenValues ?? 0) * (props.step ?? 1);
      const previous = values[index - 1];
      const following = values[index + 1];
      const min = Math.max(props.min ?? 0, previous === undefined ? -Infinity : previous + gap);
      const max = Math.min(props.max ?? 100, following === undefined ? Infinity : following - gap);
      if (commit)
        next = Math.min(max, Math.max(min, snapInput(next, props.min ?? 0, props.max ?? 100, props.step ?? 1)));
      if (next < min || next > max || next === number) return;
      const nextValues = values.map((n, i) => (i === index ? next : n));
      const details = inputChangeDetails(event, index);
      change(typeof currentValue === 'number' ? next : nextValues, details);
      return details;
    };
    return (
      <BaseSlider.Root
        {...props}
        minStepsBetweenValues={internalState.keyboard ? 0 : props.minStepsBetweenValues}
        value={currentValue}
        onValueChange={change}
        className={cn(v.root(), className)}
        {...(invalid ? { 'data-invalid': true } : {})}
        aria-invalid={ariaInvalid}
        render={(rootProps, state) => (
          <div {...rootProps}>
            {label && (
              <div className={v.header()}>
                <BaseSlider.Label className={v.label()}>{label}</BaseSlider.Label>
              </div>
            )}
            <div className={inputStyles.row()}>
              {control}
              <div className="flex gap-3">
                {state.values.map((number, index) => (
                  <BaseField.Root key={index} disabled={state.disabled}>
                    <NumberInput
                      className={inputStyles.input()}
                      role="spinbutton"
                      aria-valuemin={props.min ?? 0}
                      aria-valuemax={props.max ?? 100}
                      aria-valuenow={number}
                      aria-label={thumbLabels?.[index] ?? (!label ? ariaLabel : undefined)}
                      aria-labelledby={
                        thumbLabels?.[index] || (!label && ariaLabel) ? undefined : rootProps['aria-labelledby']
                      }
                      value={number}
                      min={props.min ?? 0}
                      max={props.max ?? 100}
                      step={props.step}
                      largeStep={props.largeStep}
                      format={props.format}
                      locale={props.locale}
                      allowOutOfRange
                      size={inputProps?.size ?? size ?? 'md'}
                      unit={inputProps?.unit}
                      hideSteppers={inputProps?.hideSteppers}
                      onValueChange={(next, details) => {
                        // Blur normalization is handled by the commit callback, once.
                        if (details.reason === 'input-blur') return;
                        if (updateInput(next, index, details.event)?.isCanceled) details.cancel();
                      }}
                      onValueCommitted={(next, details) => {
                        if (details.reason === 'input-blur') updateInput(next, index, details.event, true);
                      }}
                      onKeyDown={(event) => {
                        if (event.key !== 'Enter' || !(event.target instanceof HTMLInputElement)) return;
                        event.preventDefault();
                        // Use the same public blur normalization path for Enter and Tab.
                        event.target.blur();
                        event.target.focus();
                      }}
                    />
                  </BaseField.Root>
                ))}
              </div>
            </div>
          </div>
        )}
      />
    );
  }
  return (
    <BaseSlider.Root
      className={cn(v.root(), className)}
      {...props}
      minStepsBetweenValues={internalState.keyboard ? 0 : props.minStepsBetweenValues}
      value={currentValue}
      onValueChange={change}
      {...(invalid ? { 'data-invalid': true } : {})}
      aria-invalid={ariaInvalid}
    >
      {(label || showValue) && (
        <div className={v.header()}>
          {label && <BaseSlider.Label className={v.label()}>{label}</BaseSlider.Label>}
          {showValue && (
            <BaseSlider.Value className={cn(v.value(), !label && 'ms-auto')}>{formatValue}</BaseSlider.Value>
          )}
        </div>
      )}
      {control}
    </BaseSlider.Root>
  );
}

import { useLayoutEffect, useRef } from 'react';
import { sliderMarkVariants } from './slider.variants';

export type SliderMark = number | { value: number; label?: string };
export type LabelledMark = { value: number; label?: string };

export function normalizeMarks(marks: SliderMark[] | undefined, min: number, max: number): LabelledMark[] {
  return [
    ...new Map(
      (marks ?? [])
        .map((mark) => (typeof mark === 'number' ? { value: mark } : mark))
        .filter((mark) => Number.isFinite(mark.value) && mark.value >= min && mark.value <= max)
        .map((mark) => [mark.value, mark] as const),
    ).values(),
  ].sort((a, b) => a.value - b.value);
}

export function SliderMarkLabels({
  marks,
  values,
  min,
  max,
}: {
  marks: LabelledMark[];
  values: readonly number[];
  min: number;
  max: number;
}) {
  const row = useRef<HTMLDivElement>(null);
  const styles = sliderMarkVariants();
  const labels = marks.filter((mark) => mark.label !== undefined);
  useLayoutEffect(() => {
    const element = row.current;
    const track = element?.parentElement;
    if (!element || !track) return;
    const measure = () => {
      const width = track.getBoundingClientRect().width;
      if (!width) return;
      // Logical offsets inherit the root's computed direction, including a plain
      // dir ancestor or direction supplied by the consumer's stylesheet.
      element.style.direction = getComputedStyle(track.parentElement ?? track).direction;
      for (const child of element.children) {
        if (!(child instanceof HTMLElement)) continue;
        const labelWidth = child.getBoundingClientRect().width;
        const fraction = Number(child.dataset.position);
        const tick = width * fraction;
        child.style.insetInlineStart = `${Math.max(0, Math.min(tick - labelWidth / 2, width - labelWidth))}px`;
        child.style.insetInlineEnd = 'auto';
        child.style.transform = 'none';
        child.style.translate = 'none';
      }
    };
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(track);
    for (const child of element.children) observer.observe(child);
    return () => observer.disconnect();
  }, [marks, min, max]);
  return (
    <div ref={row} aria-hidden="true" className={styles.markLabels()}>
      {labels.map((mark, index) => {
        const position = (mark.value - min) / (max - min);
        const edge = index === 0 ? 'start' : index === labels.length - 1 ? 'end' : 'middle';
        return (
          <span
            key={mark.value}
            data-position={position}
            className={styles.markLabel({ active: values.includes(mark.value), edge })}
            style={
              edge === 'end' ? { insetInlineEnd: 0 } : { insetInlineStart: edge === 'start' ? 0 : `${position * 100}%` }
            }
          >
            {mark.label}
          </span>
        );
      })}
    </div>
  );
}

export { Slider, type SliderProps } from './Slider';
export { sliderVariants } from './slider.variants';
export { doc as sliderDoc } from './Slider.doc';

import type { ChangeEvent, ComponentProps, KeyboardEvent } from 'react';

/** Select a mark without crossing neighbours; distance is counted in mark indices. */
export function snapToMarks(
  values: readonly number[],
  thumbIndex: number,
  proposal: number,
  marks: readonly number[],
  minStepsBetweenValues: number,
) {
  const previous = values[thumbIndex - 1];
  const following = values[thumbIndex + 1];
  const previousIndex = marks.reduce(
    (last, mark, index) => (previous !== undefined && mark <= previous ? index : last),
    -1,
  );
  const followingIndex = marks.findIndex((mark) => following !== undefined && mark >= following);
  const gap = Math.max(0, minStepsBetweenValues);
  const candidates = marks.filter(
    (mark, index) =>
      (previous === undefined || (mark >= previous && index >= previousIndex + gap)) &&
      (following === undefined ||
        (mark <= following && index <= (followingIndex < 0 ? marks.length : followingIndex) - gap)),
  );
  const nearest = candidates.reduce<number | undefined>(
    (best, mark) => (best === undefined || Math.abs(mark - proposal) < Math.abs(best - proposal) ? mark : best),
    undefined,
  );
  return values.map((value, index) => (index === thumbIndex ? (nearest ?? value) : value));
}

export function markKeyDown(
  event: KeyboardEvent<HTMLInputElement>,
  inputChange: ComponentProps<'input'>['onChange'],
  values: readonly number[],
  index: number,
  marks: readonly number[],
  gap: number,
  dispatch: (change: () => void) => void,
) {
  if (event.defaultPrevented || event.currentTarget.disabled || !marks.length) return false;
  const current = values[index];
  if (current === undefined) return false;
  const input = event.currentTarget;
  const rtl =
    getComputedStyle(input).direction === 'rtl' ||
    (getComputedStyle(input).direction === '' && input.closest('[dir]')?.getAttribute('dir') === 'rtl');
  let proposal: number | undefined;
  switch (event.key) {
    case 'Home':
      proposal = marks[0];
      break;
    case 'End':
      proposal = marks[marks.length - 1];
      break;
    case 'ArrowRight':
    case 'ArrowLeft':
    case 'ArrowUp':
    case 'ArrowDown':
    case 'PageUp':
    case 'PageDown': {
      const forward =
        event.key === 'ArrowUp' || event.key === 'PageUp' || event.key === (rtl ? 'ArrowLeft' : 'ArrowRight');
      proposal = forward ? marks.find((mark) => mark > current) : [...marks].reverse().find((mark) => mark < current);
      break;
    }
    default:
      return false;
  }
  event.preventDefault();
  event.stopPropagation();
  if (proposal === undefined) return true;
  const next = snapToMarks(values, index, proposal, marks, gap)[index];
  if (next === undefined || next === current) return true;

  // Thumb's public render children expose Base UI's native input handler. Reuse it
  // with the original keyboard event so Base UI creates its own change/commit
  // details, including the Field-resolved name and keyboard reason.
  try {
    dispatch(() => {
      input.value = String(next);
      inputChange?.(event as unknown as ChangeEvent<HTMLInputElement>);
    });
  } finally {
    // Restore React's rendered value after cancellation or a controlled proposal.
    // Accepted uncontrolled updates render their new value at the end of the event.
    input.value = input.getAttribute('value') ?? String(current);
  }
  return true;
}

import { tv, type VariantProps } from '../../utils/tv';

export const sliderVariants = tv({
  slots: {
    root: 'flex w-full flex-col gap-2 data-disabled:opacity-50 data-invalid:[&_[data-index]]:border-destructive/70 aria-invalid:[&_[data-index]]:border-destructive/70',
    header: 'flex items-baseline justify-between gap-3',
    label: 'text-[13px] font-medium text-foreground',
    value: 'font-mono text-[12px] text-muted-foreground tabular-nums',
    control: 'flex w-full touch-none items-center select-none data-disabled:cursor-disabled',
    track:
      'relative w-full rounded-full bg-secondary select-none forced-colors:outline forced-colors:-outline-offset-1 forced-colors:outline-[CanvasText]',
    indicator: 'rounded-full bg-primary select-none forced-colors:bg-[Highlight]',
    thumb: [
      'rounded-full border border-primary bg-background shadow-sm transition-[scale] select-none motion-reduce:transition-none',
      'has-[:focus-visible]:outline-2 has-[:focus-visible]:outline-offset-2 has-[:focus-visible]:outline-focus-ring',
      'data-dragging:scale-110 data-disabled:cursor-disabled',
    ],
  },
  variants: {
    size: {
      sm: { control: 'py-2', track: 'h-1', thumb: 'size-3.5' },
      md: { control: 'py-2.5', track: 'h-1.5', thumb: 'size-[18px]' },
    },
  },
  defaultVariants: { size: 'md' },
});

export type SliderVariantProps = VariantProps<typeof sliderVariants>;

// Kept separate so the default public variants output and existing snapshots stay unchanged.
export const sliderInputVariants = tv({
  slots: {
    row: 'grid grid-cols-[1fr_auto] items-center gap-3',
    input: 'w-20',
  },
});

export const sliderMarkVariants = tv({
  slots: {
    mark: 'pointer-events-none absolute top-1/2 -mt-0.5 -ms-0.5 size-1 rounded-full bg-muted-foreground/50 forced-colors:bg-[CanvasText]',
    markLabels: 'pointer-events-none absolute top-full mt-3 h-4 w-full',
    markLabel: 'absolute max-w-full truncate text-[11.5px] text-muted-foreground',
  },
  variants: {
    active: {
      true: {
        mark: 'bg-primary-foreground/70 forced-colors:bg-[HighlightText]',
        markLabel: 'font-medium text-foreground',
      },
    },
    edge: { middle: { markLabel: '-translate-x-1/2 rtl:translate-x-1/2' }, start: {}, end: {} },
  },
});
